#!/usr/bin/env python3
"""Condense a captured conversation JSONL into a readable trace.

usage: condense.py <file.jsonl> [mode]
  mode = human   (default) human turns only
         trace   human turns + assistant text + one line per tool call
         time    tool-call wall-clock gaps, largest first
"""
import sys, json, datetime

path = sys.argv[1]
mode = sys.argv[2] if len(sys.argv) > 2 else 'human'
CAP = int(sys.argv[3]) if len(sys.argv) > 3 else 1800

def ts(d):
    t = d.get('timestamp')
    return t[11:19] if t else '--:--:--'

def parse(t):
    return datetime.datetime.fromisoformat(t.replace('Z', '+00:00'))

entries = []
with open(path) as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        try:
            entries.append(json.loads(line))
        except Exception:
            pass

def human_text(d):
    """Real owner text: a user entry whose content is not a tool_result."""
    if d.get('type') != 'user' or d.get('isSidechain'):
        return None
    c = d.get('message', {}).get('content')
    if isinstance(c, str):
        txt = c
    elif isinstance(c, list):
        parts = [b.get('text', '') for b in c
                 if isinstance(b, dict) and b.get('type') == 'text']
        if not parts:
            return None
        txt = '\n'.join(parts)
    else:
        return None
    if not txt.strip():
        return None
    return txt

timeline = []
for d in entries:
    h = human_text(d)
    if h is not None:
        timeline.append(('HUMAN', ts(d), h, d))
        continue
    if d.get('type') == 'assistant' and not d.get('isSidechain'):
        for b in d.get('message', {}).get('content', []) or []:
            if not isinstance(b, dict):
                continue
            if b.get('type') == 'text' and b.get('text', '').strip():
                timeline.append(('CLAUDE', ts(d), b['text'], d))
            elif b.get('type') == 'tool_use':
                inp = b.get('input', {})
                brief = inp.get('command') or inp.get('file_path') or \
                    inp.get('pattern') or inp.get('prompt') or inp.get('skill') or \
                    inp.get('query') or inp.get('url') or json.dumps(inp)[:200]
                timeline.append(('TOOL', ts(d), f"{b.get('name')}: {str(brief)[:200]}", d))

if mode == 'time':
    rows = []
    prev = None
    for kind, t, txt, d in timeline:
        cur = d.get('timestamp')
        if prev and cur:
            gap = (parse(cur) - parse(prev)).total_seconds()
            rows.append((gap, t, kind, txt[:120]))
        prev = cur or prev
    rows.sort(reverse=True)
    total = sum(r[0] for r in rows)
    print(f"entries={len(entries)} steps={len(rows)} span_total={total/60:.1f}min")
    for gap, t, kind, txt in rows[:30]:
        print(f"{gap:8.1f}s  {t}  {kind:6} {txt}")
    sys.exit(0)

for kind, t, txt, d in timeline:
    if mode == 'human' and kind != 'HUMAN':
        continue
    if kind == 'HUMAN' and txt.lstrip().startswith('<system-reminder>'):
        continue
    body = txt if len(txt) <= CAP else txt[:CAP] + f'  …[+{len(txt)-CAP}]'
    print(f"\n[{t}] {kind}: {body}")

