python3 - <<'PY'
import re, os, subprocess
pat = re.compile(r'`([A-Za-z0-9_.-]+(?:/[A-Za-z0-9_.-]+)+\.(?:mjs|json|md|yml|yaml|sh|js))`')
files = subprocess.run(['git','ls-files','.claudinite/local/packs/claudinite'],capture_output=True,text=True).stdout.split()
seen = {}
for f in files:
    try: txt = open(f).read()
    except Exception: continue
    if f.endswith('.md'):
        txt = re.sub(r'```.*?```', lambda m: '\n'*m.group(0).count('\n'), txt, flags=re.S)
    for i, line in enumerate(txt.split('\n'), 1):
        for m in pat.finditer(line):
            seen.setdefault(m.group(1), []).append((f,i))
print(f"files={len(files)} distinct={len(seen)}")
miss=[(p,o) for p,o in seen.items() if not os.path.exists(p)]
print(f"MISSING {len(miss)}:")
for p,o in sorted(miss): print("  ",p,"<-",o[0], f"(x{len(o)})")
PY

