val = re.compile(r'`(?P<value>(?:packs|engine)/[A-Za-z0-9_.-]+(?:/[A-Za-z0-9_.-]+)*\.(?:mjs|json|md|yml|yaml|sh))`')
sel = re.compile(r'(^|/)(?:packs|\.claudinite/local/packs)/[^/]+/(RULES\.md|skills/[^/]+/SKILL\.md)$')
files=[f for f in subprocess.run(['git','ls-files'],capture_output=True,text=True).stdout.split() if sel.search(f)]
tot=0; miss=[]
for f in files:
    txt=open(f).read()
    txt=re.sub(r'```.*?```', lambda m:'\n'*m.group(0).count('\n'), txt, flags=re.S)
    for i,l in enumerate(txt.split('\n'),1):
        for m in val.finditer(l):
            tot+=1
            if not os.path.exists(m.group('value')): miss.append((f,i,m.group('value')))
print(f"files={len(files)} values={tot} missing={len(miss)}")
for f,i,v in miss: print(f"  {f}:{i}  {v}")
PY

